#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

static const ll mod = 998244353;
static vector<ll> pw;

void init(ll n, int k) {
    pw.assign(k, 0);
    pw[0] = 1;
    for (int i = 1; i < k; i++) {
        pw[i] = (n * pw[i - 1]) % mod;
    }
}

ll ggt(ll a, ll b) {
    if (a < b) return ggt(b, a);
    if (b == 0) return a;
    return ggt(b, a % b);
}

ll gcd_(ll a, ll b) {
    return a * b / ggt(a, b);
}

int gcdRange(ll n) {
    int gcd = 1;
    for (int i = 1; i <= n; i++) gcd = (int) gcd_(gcd, i);
    return gcd;
}

void solve(int n, ll a, ll x, ll y, int k, ll M) {
    init(n, k);

    int gcdR = gcdRange(k - 1);

    vector<vector<ll>> r(gcdR, vector<ll>(k + 1, 0));

    for (int i = 1; i <= k; i++) {
        for (int j = 0; j < gcdR; j++) {
            int jump = j - (j % (k + 1 - i));
            r[j][i] = (((ll)(n - 1) * r[j][i - 1]) + (r[jump][i - 1] + (ll)j * pw[i - 1])) % mod;
        }
    }

    ll sum = 0;
    for (int i = 0; i < n; i++) {
        sum += r[(int)(a % gcdR)][k] + ((((a / gcdR) * gcdR * k) % mod) * pw[k - 1]) % mod;
        sum %= mod;
        a = (a * x + y) % M;
    }

    cout << sum << endl;
}

int main() {
    int n, a, x, y, k, M;
    cin >> n >> a >> x >> y >> k >> M;
    solve(n, a, x, y, k, M);
    return 0;
}
